-- Isolated HR v2 schema. It intentionally uses hr_v2_* objects and does not reuse legacy application tables.
create type public.hr_v2_role as enum ('admin','accountant','employee');
create type public.hr_v2_employee_status as enum ('inactive','active','suspended');
create type public.hr_v2_attendance_status as enum ('present','absent','late','leave','rest','sick_leave','missing_checkout');
create type public.hr_v2_money_type as enum ('advance','deduction','bonus','other');
create type public.hr_v2_approval_status as enum ('pending','approved','rejected');
create type public.hr_v2_payroll_status as enum ('draft','approved','paid');
create table public.hr_v2_branches(id uuid primary key default gen_random_uuid(),name text not null,address text,phone text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.hr_v2_employees(id uuid primary key default gen_random_uuid(),employee_no text unique,full_name_ar text not null,full_name_en text,phone text unique,position text,branch_id uuid references public.hr_v2_branches(id),base_salary numeric(12,2) not null default 0,pay_type text not null default 'monthly',overtime_rate numeric(12,2) not null default 0,daily_work_hours numeric(5,2) not null default 8,work_schedule jsonb not null default '{}'::jsonb,hire_date date,status public.hr_v2_employee_status not null default 'inactive',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.hr_v2_accounts(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,phone text unique,role public.hr_v2_role not null,employee_id uuid unique references public.hr_v2_employees(id),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.hr_v2_attendance(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.hr_v2_employees(id),work_date date not null,check_in timestamptz,check_out timestamptz,late_minutes integer not null default 0,work_minutes integer not null default 0,overtime_minutes integer not null default 0,status public.hr_v2_attendance_status not null default 'present',notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(employee_id,work_date));
create table public.hr_v2_overtime(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.hr_v2_employees(id),work_date date not null,hours numeric(8,2) not null check(hours>=0),hourly_rate numeric(12,2) not null default 0,amount numeric(12,2) generated always as (round(hours*hourly_rate,2)) stored,reason text,approval_status public.hr_v2_approval_status not null default 'pending',approved_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.hr_v2_money_transactions(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.hr_v2_employees(id),transaction_date date not null,type public.hr_v2_money_type not null,amount numeric(12,2) not null check(amount>=0),reason text,notes text,approval_status public.hr_v2_approval_status not null default 'pending',approved_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.hr_v2_payroll(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.hr_v2_employees(id),period_start date not null,period_end date not null,base_salary numeric(12,2) not null default 0,attendance_deduction numeric(12,2) not null default 0,lateness_deduction numeric(12,2) not null default 0,overtime_total numeric(12,2) not null default 0,bonuses numeric(12,2) not null default 0,deductions numeric(12,2) not null default 0,advances numeric(12,2) not null default 0,net_salary numeric(12,2) not null default 0,status public.hr_v2_payroll_status not null default 'draft',approved_by uuid references auth.users(id),approved_at timestamptz,created_at timestamptz not null default now(),unique(employee_id,period_start,period_end));
create table public.hr_v2_payroll_items(id uuid primary key default gen_random_uuid(),payroll_id uuid not null references public.hr_v2_payroll(id) on delete cascade,item_type text not null,amount numeric(12,2) not null,description text,created_at timestamptz not null default now());
create table public.hr_v2_audit_logs(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id),action text not null,entity text not null,entity_id uuid,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.hr_v2_settings(id uuid primary key default gen_random_uuid(),key text unique not null,value jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index hr_v2_employees_branch_idx on public.hr_v2_employees(branch_id);create index hr_v2_employees_status_idx on public.hr_v2_employees(status);create index hr_v2_attendance_date_idx on public.hr_v2_attendance(work_date);create index hr_v2_overtime_employee_date_idx on public.hr_v2_overtime(employee_id,work_date);create index hr_v2_money_employee_date_idx on public.hr_v2_money_transactions(employee_id,transaction_date);create index hr_v2_payroll_period_idx on public.hr_v2_payroll(period_start,period_end);
create or replace function public.hr_v2_role() returns public.hr_v2_role language sql stable security invoker set search_path=public as $$ select role from public.hr_v2_accounts where id=auth.uid() and is_active=true limit 1 $$;
create or replace function public.hr_v2_is_admin() returns boolean language sql stable security invoker set search_path=public as $$ select coalesce(public.hr_v2_role()='admin',false) $$;
create or replace function public.hr_v2_is_manager() returns boolean language sql stable security invoker set search_path=public as $$ select coalesce(public.hr_v2_role() in ('admin','accountant'),false) $$;
create or replace function public.hr_v2_resolve_login(p_identifier text) returns text language plpgsql security definer set search_path=public,auth as $$ declare v_email text; begin select u.email into v_email from auth.users u join public.hr_v2_accounts a on a.id=u.id where (a.phone=p_identifier or u.email=p_identifier) and a.is_active=true limit 1; return v_email; end; $$;
revoke all on function public.hr_v2_resolve_login(text) from public;grant execute on function public.hr_v2_resolve_login(text) to anon,authenticated;
alter table public.hr_v2_branches enable row level security;alter table public.hr_v2_employees enable row level security;alter table public.hr_v2_accounts enable row level security;alter table public.hr_v2_attendance enable row level security;alter table public.hr_v2_overtime enable row level security;alter table public.hr_v2_money_transactions enable row level security;alter table public.hr_v2_payroll enable row level security;alter table public.hr_v2_payroll_items enable row level security;alter table public.hr_v2_audit_logs enable row level security;alter table public.hr_v2_settings enable row level security;
create policy hr_v2_branches_select on public.hr_v2_branches for select to authenticated using(public.hr_v2_role() in ('admin','accountant'));create policy hr_v2_branches_write on public.hr_v2_branches for all to authenticated using(public.hr_v2_is_admin()) with check(public.hr_v2_is_admin());create policy hr_v2_employees_select on public.hr_v2_employees for select to authenticated using(public.hr_v2_is_manager() or exists(select 1 from public.hr_v2_accounts a where a.id=auth.uid() and a.employee_id=hr_v2_employees.id));create policy hr_v2_employees_write on public.hr_v2_employees for all to authenticated using(public.hr_v2_is_admin()) with check(public.hr_v2_is_admin());create policy hr_v2_accounts_self on public.hr_v2_accounts for select to authenticated using(id=auth.uid() or public.hr_v2_is_admin());create policy hr_v2_accounts_admin on public.hr_v2_accounts for all to authenticated using(public.hr_v2_is_admin()) with check(public.hr_v2_is_admin());create policy hr_v2_attendance_select on public.hr_v2_attendance for select to authenticated using(public.hr_v2_is_manager() or exists(select 1 from public.hr_v2_accounts a where a.id=auth.uid() and a.employee_id=hr_v2_attendance.employee_id));create policy hr_v2_attendance_manager_write on public.hr_v2_attendance for all to authenticated using(public.hr_v2_is_manager()) with check(public.hr_v2_is_manager());create policy hr_v2_overtime_select on public.hr_v2_overtime for select to authenticated using(public.hr_v2_is_manager() or exists(select 1 from public.hr_v2_accounts a where a.id=auth.uid() and a.employee_id=hr_v2_overtime.employee_id));create policy hr_v2_overtime_manager_write on public.hr_v2_overtime for all to authenticated using(public.hr_v2_is_manager()) with check(public.hr_v2_is_manager());create policy hr_v2_money_select on public.hr_v2_money_transactions for select to authenticated using(public.hr_v2_is_manager() or exists(select 1 from public.hr_v2_accounts a where a.id=auth.uid() and a.employee_id=hr_v2_money_transactions.employee_id));create policy hr_v2_money_manager_write on public.hr_v2_money_transactions for all to authenticated using(public.hr_v2_is_manager()) with check(public.hr_v2_is_manager());create policy hr_v2_payroll_select on public.hr_v2_payroll for select to authenticated using(public.hr_v2_is_manager() or exists(select 1 from public.hr_v2_accounts a where a.id=auth.uid() and a.employee_id=hr_v2_payroll.employee_id));create policy hr_v2_payroll_manager_write on public.hr_v2_payroll for all to authenticated using(public.hr_v2_is_manager()) with check(public.hr_v2_is_manager());create policy hr_v2_payroll_items_select on public.hr_v2_payroll_items for select to authenticated using(exists(select 1 from public.hr_v2_payroll p where p.id=payroll_id and (public.hr_v2_is_manager() or exists(select 1 from public.hr_v2_accounts a where a.id=auth.uid() and a.employee_id=p.employee_id))));create policy hr_v2_payroll_items_write on public.hr_v2_payroll_items for all to authenticated using(public.hr_v2_is_manager()) with check(public.hr_v2_is_manager());create policy hr_v2_audit_admin on public.hr_v2_audit_logs for select to authenticated using(public.hr_v2_is_admin());create policy hr_v2_settings_admin on public.hr_v2_settings for all to authenticated using(public.hr_v2_is_admin());
grant select,insert,update,delete on public.hr_v2_branches,public.hr_v2_employees,public.hr_v2_accounts,public.hr_v2_attendance,public.hr_v2_overtime,public.hr_v2_money_transactions,public.hr_v2_payroll,public.hr_v2_payroll_items,public.hr_v2_audit_logs,public.hr_v2_settings to authenticated;grant execute on function public.hr_v2_role(),public.hr_v2_is_admin(),public.hr_v2_is_manager() to authenticated;
